/**
 * KARJMUKTBHARAT core business logic. Pure functions only: no I/O, no Date.now(),
 * no globals. Every number on the landing page and dashboard is derived from here,
 * so changing BLOCK_RULES or a live user count updates the whole UI.
 *
 * Model (per block of 1000 users, per month):
 *   1 block = 1000 users = Rs 1 Crore
 *   Education: Borrower 15L + CSR 85L. 80% CSR (68L) -> RESCUE (22 students)
 *              20% CSR (17L) + borrower 15L = 32L -> REGULAR (Rs 3,200 / user / month)
 *   Home:      Borrower 30L + CSR 70L. 80% CSR (56L) -> RESCUE (11 houses)
 *              20% CSR (14L) + borrower 30L = 44L -> REGULAR (Rs 4,400 / user / month)
 *
 * All money is in whole rupees. Money goes directly to the bank loan account; there is no wallet.
 */

export type BlockType = 'education' | 'home'

export const LAKH = 1_00_000
export const CRORE = 1_00_00_000

export interface BlockRule {
  /** Users in one full block */
  blockSize: number
  /** Total monthly pool of one full block */
  blockValue: number
  /** Borrower contribution of one full block */
  borrowerPool: number
  /** CSR contribution of one full block */
  csrPool: number
  /** Share of CSR that goes to the rescue pool (rest joins the regular pool) */
  rescueShareOfCsr: number
  /** Average outstanding amount needed to rescue one case (auction / default) */
  avgRescueTicket: number
  /** Target user base for this loan type */
  targetUsers: number
}

export const BLOCK_RULES: Readonly<Record<BlockType, BlockRule>> = Object.freeze({
  education: {
    blockSize: 1000,
    blockValue: 1 * CRORE,
    borrowerPool: 15 * LAKH,
    csrPool: 85 * LAKH,
    rescueShareOfCsr: 0.8,
    avgRescueTicket: 3 * LAKH,
    targetUsers: 5 * LAKH, // 5 lakh users
  },
  home: {
    blockSize: 1000,
    blockValue: 1 * CRORE,
    borrowerPool: 30 * LAKH,
    csrPool: 70 * LAKH,
    rescueShareOfCsr: 0.8,
    avgRescueTicket: 5 * LAKH,
    targetUsers: 20 * LAKH, // 20 lakh users
  },
})

export const BLOCK_TYPES: readonly BlockType[] = ['education', 'home'] as const

function rule(blockType: BlockType, rules: Readonly<Record<BlockType, BlockRule>> = BLOCK_RULES): BlockRule {
  const r = rules[blockType]
  if (!r) throw new Error(`Unknown block type: ${String(blockType)}`)
  return r
}

function assertUsers(users: number): void {
  if (!Number.isFinite(users) || users < 0 || !Number.isInteger(users)) {
    throw new RangeError(`users must be a non-negative integer, got ${users}`)
  }
}

export interface BlockBreakdown {
  blockType: BlockType
  users: number
  borrowerPool: number
  csrPool: number
  totalPool: number
  rescuePool: number
  regularPool: number
  rescueCapacity: number
  regularPerUser: number
  borrowerContributionPerUser: number
}

/**
 * Full pool split for one block. `users` defaults to a full block (1000);
 * a partially filled block scales linearly so per-user numbers stay constant.
 */
export function calculateBlockBreakdown(
  blockType: BlockType,
  users: number = rule(blockType).blockSize,
  rules: Readonly<Record<BlockType, BlockRule>> = BLOCK_RULES,
): BlockBreakdown {
  const r = rule(blockType, rules)
  assertUsers(users)
  if (users > r.blockSize) throw new RangeError(`A block holds at most ${r.blockSize} users`)

  const fill = users / r.blockSize
  const borrowerPool = Math.round(r.borrowerPool * fill)
  const csrPool = Math.round(r.csrPool * fill)
  const rescuePool = Math.round(csrPool * r.rescueShareOfCsr)
  const regularPool = csrPool - rescuePool + borrowerPool

  return {
    blockType,
    users,
    borrowerPool,
    csrPool,
    totalPool: borrowerPool + csrPool,
    rescuePool,
    regularPool,
    rescueCapacity: Math.floor(rescuePool / r.avgRescueTicket),
    regularPerUser: users === 0 ? 0 : Math.floor(regularPool / users),
    borrowerContributionPerUser: r.borrowerPool / r.blockSize,
  }
}

/** Extra rupees paid into each member's loan account per month (3200 education, 4400 home). */
export function calculateRegularPerUser(blockType: BlockType, rules = BLOCK_RULES): number {
  return calculateBlockBreakdown(blockType, rule(blockType, rules).blockSize, rules).regularPerUser
}

/** Cases one full block rescues per month (22 education, 11 home). */
export function calculateRescueCapacity(blockType: BlockType, rules = BLOCK_RULES): number {
  return calculateBlockBreakdown(blockType, rule(blockType, rules).blockSize, rules).rescueCapacity
}

export interface BlockCount {
  fullBlocks: number
  partialBlockUsers: number
  totalBlocks: number
}

export function calculateBlockCount(blockType: BlockType, users: number, rules = BLOCK_RULES): BlockCount {
  assertUsers(users)
  const size = rule(blockType, rules).blockSize
  const fullBlocks = Math.floor(users / size)
  const partialBlockUsers = users % size
  return { fullBlocks, partialBlockUsers, totalBlocks: fullBlocks + (partialBlockUsers > 0 ? 1 : 0) }
}

export interface TypeTotals extends BlockCount {
  blockType: BlockType
  users: number
  totalPool: number
  borrowerPool: number
  csrPool: number
  rescuePool: number
  regularPool: number
  rescueCapacity: number
  regularPerUser: number
}

/**
 * Monthly totals for one loan type given the live user count.
 * Rescue capacity is counted per block (a partial block rescues what its own pool can fund).
 */
export function calculateTypeTotals(blockType: BlockType, users: number, rules = BLOCK_RULES): TypeTotals {
  const count = calculateBlockCount(blockType, users, rules)
  const full = calculateBlockBreakdown(blockType, rule(blockType, rules).blockSize, rules)
  const partial = calculateBlockBreakdown(blockType, count.partialBlockUsers, rules)
  const n = count.fullBlocks
  return {
    blockType,
    users,
    ...count,
    borrowerPool: full.borrowerPool * n + partial.borrowerPool,
    csrPool: full.csrPool * n + partial.csrPool,
    totalPool: full.totalPool * n + partial.totalPool,
    rescuePool: full.rescuePool * n + partial.rescuePool,
    regularPool: full.regularPool * n + partial.regularPool,
    rescueCapacity: full.rescueCapacity * n + partial.rescueCapacity,
    regularPerUser: full.regularPerUser,
  }
}

export interface PlatformTotals {
  users: number
  blocks: number
  monthlyPool: number
  monthlyCsr: number
  monthlyRescuePool: number
  monthlyRegularPool: number
  monthlyRescueCapacity: number
  byType: Record<BlockType, TypeTotals>
}

export function calculatePlatformTotals(usersByType: Record<BlockType, number>, rules = BLOCK_RULES): PlatformTotals {
  const education = calculateTypeTotals('education', usersByType.education, rules)
  const home = calculateTypeTotals('home', usersByType.home, rules)
  const both = [education, home]
  const sum = (k: keyof TypeTotals) => both.reduce((a, t) => a + (t[k] as number), 0)
  return {
    users: sum('users'),
    blocks: sum('totalBlocks'),
    monthlyPool: sum('totalPool'),
    monthlyCsr: sum('csrPool'),
    monthlyRescuePool: sum('rescuePool'),
    monthlyRegularPool: sum('regularPool'),
    monthlyRescueCapacity: sum('rescueCapacity'),
    byType: { education, home },
  }
}

/** Platform at its 25 lakh target (5L education + 20L home). */
export function calculateTargetTotals(rules = BLOCK_RULES): PlatformTotals {
  return calculatePlatformTotals({ education: rules.education.targetUsers, home: rules.home.targetUsers }, rules)
}

// ---------------------------------------------------------------------------
// Loan maths
// ---------------------------------------------------------------------------

export interface LoanInput {
  /** Outstanding principal in rupees */
  principal: number
  /** Annual interest rate in percent, e.g. 9.5 */
  annualRatePct: number
  /** Current monthly EMI in rupees */
  emi: number
}

function assertLoan({ principal, annualRatePct, emi }: LoanInput, extra = 0): void {
  if (![principal, annualRatePct, emi, extra].every(Number.isFinite)) throw new RangeError('Loan values must be finite numbers')
  if (principal < 0 || annualRatePct < 0 || emi < 0 || extra < 0) throw new RangeError('Loan values must not be negative')
}

export const MAX_TENURE_MONTHS = 600 // 50 years: anything longer is treated as "never repaid"

export interface AmortizationPoint {
  month: number
  balance: number
  interestPaidToDate: number
}

export interface AmortizationResult {
  /** Months to close the loan, or Infinity if the payment never covers interest */
  months: number
  totalInterest: number
  totalPaid: number
  series: AmortizationPoint[]
}

/** Month-by-month reducing balance schedule. The last payment is partial. */
export function amortize(loan: LoanInput, extra = 0, maxMonths = MAX_TENURE_MONTHS): AmortizationResult {
  assertLoan(loan, extra)
  const r = loan.annualRatePct / 12 / 100
  const payment = loan.emi + extra
  let balance = loan.principal
  let interestTotal = 0
  let paidTotal = 0
  const series: AmortizationPoint[] = [{ month: 0, balance, interestPaidToDate: 0 }]

  if (balance === 0) return { months: 0, totalInterest: 0, totalPaid: 0, series }
  if (payment <= balance * r || payment === 0) {
    return { months: Infinity, totalInterest: Infinity, totalPaid: Infinity, series }
  }

  let month = 0
  while (balance > 0.005 && month < maxMonths) {
    month += 1
    const interest = balance * r
    const due = balance + interest
    const pay = Math.min(payment, due)
    balance = due - pay
    interestTotal += interest
    paidTotal += pay
    series.push({ month, balance: Math.max(0, Math.round(balance)), interestPaidToDate: Math.round(interestTotal) })
  }
  if (balance > 0.005) return { months: Infinity, totalInterest: Infinity, totalPaid: Infinity, series }

  return { months: month, totalInterest: Math.round(interestTotal), totalPaid: Math.round(paidTotal), series }
}

/**
 * New tenure in months when `extra` is added to every EMI.
 * Returns Infinity when the payment does not cover monthly interest.
 */
export function calculateNewTenure(principal: number, annualRatePct: number, emi: number, extra: number): number {
  return amortize({ principal, annualRatePct, emi }, extra).months
}

export interface InterestSaving {
  oldMonths: number
  newMonths: number
  monthsSaved: number
  oldInterest: number
  newInterest: number
  interestSaved: number
}

/** Interest and months saved by paying `extra` on top of the EMI every month. */
export function calculateInterestSaved(principal: number, annualRatePct: number, emi: number, extra: number): InterestSaving {
  const before = amortize({ principal, annualRatePct, emi }, 0)
  const after = amortize({ principal, annualRatePct, emi }, extra)
  const finite = Number.isFinite(before.totalInterest)
  return {
    oldMonths: before.months,
    newMonths: after.months,
    monthsSaved: finite ? before.months - after.months : Infinity,
    oldInterest: before.totalInterest,
    newInterest: after.totalInterest,
    interestSaved: finite ? before.totalInterest - after.totalInterest : Infinity,
  }
}

/** Two aligned balance curves for the dashboard tenure chart. */
export function buildTenureComparison(loan: LoanInput, extra: number, maxPoints = 60) {
  const before = amortize(loan, 0)
  const after = amortize(loan, extra)
  const lastMonth = Math.max(
    Number.isFinite(before.months) ? before.months : before.series.length - 1,
    Number.isFinite(after.months) ? after.months : after.series.length - 1,
  )
  const step = Math.max(1, Math.ceil(lastMonth / maxPoints))
  const points: { month: number; withoutKarjmukt: number; withKarjmukt: number }[] = []
  for (let m = 0; m <= lastMonth; m += step) {
    points.push({
      month: m,
      withoutKarjmukt: before.series[m]?.balance ?? 0,
      withKarjmukt: after.series[m]?.balance ?? 0,
    })
  }
  if (points[points.length - 1]?.month !== lastMonth) {
    points.push({ month: lastMonth, withoutKarjmukt: before.series[lastMonth]?.balance ?? 0, withKarjmukt: after.series[lastMonth]?.balance ?? 0 })
  }
  return points
}

/** Standard EMI for a fresh loan (used to prefill onboarding). */
export function calculateEmi(principal: number, annualRatePct: number, months: number): number {
  if (months <= 0) throw new RangeError('months must be positive')
  const r = annualRatePct / 12 / 100
  if (r === 0) return Math.ceil(principal / months)
  const f = Math.pow(1 + r, months)
  return Math.ceil((principal * r * f) / (f - 1))
}
